    # Visit a parse tree produced by GeLBParser#constant_definition_stmt.
    def visitConstant_definition_stmt(
            self,
            ctx: GeLBParser.Constant_definition_stmtContext
    ):
        # NOTE: 'type' label becomes 'type_' due to Python keyword conflict
        data_type = self.visit(ctx.type_)
        assignment = self.visit(ctx.assignment)
        return ConstantDefinitionStmt_N(
            code_range_from_ctx(ctx),
            data_type,
            assignment.lhs,
            assignment.rhs
        )

    # Visit a parse tree produced by GeLBParser#variable_assignment_stmt.
    def visitVariable_assignment_stmt(
            self,
            ctx: GeLBParser.Variable_assignment_stmtContext
    ):
        return VariableAssignmentStmt_N(
            code_range_from_ctx(ctx),
            self.visit(ctx.lhs),
            self.visit(ctx.rhs)
        )

    # Visit a parse tree produced by GeLBParser#variable_declaration_stmt.
    def visitVariable_declaration_stmt(
            self,
            ctx: GeLBParser.Variable_declaration_stmtContext
    ):
        # NOTE: 'type' label becomes 'type_' due to Python keyword conflict
        return VariableDeclarationStmt_N(
            code_range_from_ctx(ctx),
            self.visit(ctx.type_),
            self.visit(ctx.name)
        )

    def visitVariable_declaration_with_init_stmt(
            self,
            ctx: GeLBParser.Variable_declaration_with_init_stmtContext
    ):
        # NOTE: 'type' label becomes 'type_' due to Python keyword conflict
        # Create a variable declaration with the type and assignment info
        assignment = self.visit(ctx.assignment)
        return VariableDeclarationStmt_N(
            code_range_from_ctx(ctx),
            self.visit(ctx.type_),
            assignment.lhs,  # The identifier from the assignment
            assignment.rhs   # The initial value expression
        )

    # Visit a parse tree produced by GeLBParser#scalar_bool_data_type.
    def visitScalar_bool_data_type(
            self,
            ctx: GeLBParser.Scalar_bool_data_typeContext
    ):
        empty_shape = List_N(code_range_from_ctx(ctx))
        return ArrayDataType_N(
            code_range_from_ctx(ctx),
            "bool",
            empty_shape
        )

    # Visit a parse tree produced by GeLBParser#scalar_int_data_type.
    def visitScalar_int_data_type(
            self,
            ctx: GeLBParser.Scalar_int_data_typeContext
    ):
        empty_shape = List_N(code_range_from_ctx(ctx))
        if ctx.INT64():
            return ArrayDataType_N(code_range_from_ctx(ctx), "int64", empty_shape)
        elif ctx.INT32():
            return ArrayDataType_N(code_range_from_ctx(ctx), "int32", empty_shape)
        elif ctx.INT16():
            return ArrayDataType_N(code_range_from_ctx(ctx), "int16", empty_shape)
        elif ctx.INT8():
            return ArrayDataType_N(code_range_from_ctx(ctx), "int8", empty_shape)
        elif ctx.INT():
            return ArrayDataType_N(code_range_from_ctx(ctx), "int", empty_shape)

    # Visit a parse tree produced by GeLBParser#scalar_real_data_type.
    def visitScalar_real_data_type(
            self,
            ctx: GeLBParser.Scalar_real_data_typeContext
    ):
        empty_shape = List_N(code_range_from_ctx(ctx))
        if ctx.REAL64():
            return ArrayDataType_N(code_range_from_ctx(ctx), "real64", empty_shape)
        elif ctx.REAL32():
            return ArrayDataType_N(code_range_from_ctx(ctx), "real32", empty_shape)
        elif ctx.REAL16():
            return ArrayDataType_N(code_range_from_ctx(ctx), "real16", empty_shape)
        elif ctx.REAL():
            return ArrayDataType_N(code_range_from_ctx(ctx), "real", empty_shape)

    # Visit a parse tree produced by GeLBParser#array_data_type.
    def visitArray_data_type(
            self,
            ctx: GeLBParser.Array_data_typeContext
    ):
        # For array types, extract the scalar string from the element type
        element_type_node = self.visit(ctx.element_type)
        if isinstance(element_type_node, ArrayDataType_N):
            # Element type is a 0D array, extract the scalar string
            scalar_type = element_type_node.element_dtype
        else:
            # Legacy fallback
            scalar_type = element_type_node
        
        return ArrayDataType_N(
            code_range_from_ctx(ctx),
            scalar_type,
            self.visit(ctx.shape)
        )

    # Visit a parse tree produced by GeLBParser#array_shape.
    def visitArray_shape(
            self,
            ctx: GeLBParser.Array_shapeContext
    ):
        # array_shape can be either array_literal_1d or expr
        if ctx.array_literal_1d():
            return self.visit(ctx.array_literal_1d())
        elif ctx.expr():
            return self.visit(ctx.expr())
        else:
            assert False, "Unknown array_shape alternative"

    # Visit a parse tree produced by GeLBParser#array_literal_4d.
    def visitArray_literal_4d(
            self,
            ctx: GeLBParser.Array_literal_4dContext
    ):
        elements = List_N(code_range_from_ctx(ctx))
        for elem in ctx.elements:
            elements.append(self.visit(elem))
        return Array4DLiteral_N(code_range_from_ctx(ctx), elements)

    # Visit a parse tree produced by GeLBParser#array_literal_3d.
    def visitArray_literal_3d(
            self,
            ctx: GeLBParser.Array_literal_3dContext
    ):
        elements = List_N(code_range_from_ctx(ctx))
        for elem in ctx.elements:
            elements.append(self.visit(elem))
        return Array3DLiteral_N(code_range_from_ctx(ctx), elements)

    # Visit a parse tree produced by GeLBParser#array_literal_2d.
    def visitArray_literal_2d(
            self,
            ctx: GeLBParser.Array_literal_2dContext
    ):
        elements = List_N(code_range_from_ctx(ctx))
        for elem in ctx.elements:
            elements.append(self.visit(elem))
        return Array2DLiteral_N(code_range_from_ctx(ctx), elements)

    # Visit a parse tree produced by GeLBParser#array_literal_1d.
    def visitArray_literal_1d(
            self,
            ctx: GeLBParser.Array_literal_1dContext
    ):
        elements = List_N(code_range_from_ctx(ctx))
        for elem in ctx.elements:
            elements.append(self.visit(elem))
        return Array1DLiteral_N(code_range_from_ctx(ctx), elements)

    # Visit a parse tree produced by GeLBParser#identifier.
    def visitIdentifier(
            self,
            ctx: GeLBParser.IdentifierContext
    ):
        return Identifier_N(code_range_from_ctx(ctx), str(ctx.ID()))

    # Visit a parse tree produced by GeLBParser#expr.
    def visitExpr(
            self,
            ctx: GeLBParser.ExprContext
    ):
        if isinstance(ctx, GeLBParser.NonNegIntLiteralExprContext):
            return self.visitNonNegIntLiteralExpr(ctx)
        elif isinstance(ctx, GeLBParser.NonNegRealLiteralExprContext):
            return self.visitNonNegRealLiteralExpr(ctx)
        elif isinstance(ctx, GeLBParser.BoolLiteralExprContext):
            return self.visitBoolLiteralExpr(ctx)
        elif isinstance(ctx, GeLBParser.ArrayLiteralExprContext):
            return self.visitArrayLiteralExpr(ctx)
        elif isinstance(ctx, GeLBParser.PowExprContext):
            return self.visitPowExpr(ctx)
        elif isinstance(ctx, GeLBParser.ParensExprContext):
            return self.visitParensExpr(ctx)
        elif isinstance(ctx, GeLBParser.UnaryExprContext):
            return self.visitUnaryExpr(ctx)
        elif isinstance(ctx, GeLBParser.InfixExprContext):
            return self.visitInfixExpr(ctx)
        elif isinstance(ctx, GeLBParser.IdentifierExprContext):
            return self.visitIdentifierExpr(ctx)
        elif isinstance(ctx, GeLBParser.ComparisonExprContext):
            return self.visitComparisonExpr(ctx)
        elif isinstance(ctx, GeLBParser.EqualityExprContext):
            return self.visitEqualityExpr(ctx)
        elif isinstance(ctx, GeLBParser.LogicalAndExprContext):
            return self.visitLogicalAndExpr(ctx)
        elif isinstance(ctx, GeLBParser.LogicalOrExprContext):
            return self.visitLogicalOrExpr(ctx)
        elif isinstance(ctx, GeLBParser.RectSelOfLatticeInDFsExprContext):
            return self.visitRectSelOfLatticeInDFsExpr(ctx)
        elif isinstance(ctx, GeLBParser.RectSelOfArrayElemsExprContext):
            return self.visitRectSelOfArrayElemsExpr(ctx)
        else:
            assert False, "Unknown expression type: {}".format(type(ctx))

    # Visit a parse tree produced by GeLBParser#parensExpr.
    def visitParensExpr(
            self,
            ctx: GeLBParser.ParensExprContext
    ):
        return self.visit(ctx.expr())

    # Visit a parse tree produced by GeLBParser#infixExpr.
    def visitInfixExpr(
            self,
            ctx: GeLBParser.InfixExprContext
    ):
        if ctx.op.text == '*':
            return Mul_N(
                code_range_from_ctx(ctx),
                self.visit(ctx.left),
                self.visit(ctx.right)
            )
        elif ctx.op.text == '/':
            return Div_N(
                code_range_from_ctx(ctx),
                self.visit(ctx.left),
                self.visit(ctx.right)
            )
        elif ctx.op.text == '+':
            return Add_N(
                code_range_from_ctx(ctx),
                self.visit(ctx.left),
                self.visit(ctx.right)
            )
        elif ctx.op.text == '-':
            return Sub_N(
                code_range_from_ctx(ctx),
                self.visit(ctx.left),
                self.visit(ctx.right)
            )

    # Visit a parse tree produced by GeLBParser#unaryExpr.
    def visitUnaryExpr(
            self,
            ctx: GeLBParser.UnaryExprContext
    ):
        if ctx.op.text == '+':
            return self.visit(ctx.expr())
        elif ctx.op.text == '-':
            return UnaryMinusExpr_N(
                code_range_from_ctx(ctx),
                self.visit(ctx.expr())
            )
        elif ctx.op.text == '!':
            return NotExpr_N(
                code_range_from_ctx(ctx),
                self.visit(ctx.expr())
            )

    # Visit a parse tree produced by GeLBParser#nonNegRealLiteralExpr.
    def visitNonNegRealLiteralExpr(
            self,
            ctx: GeLBParser.NonNegRealLiteralExprContext
    ):
        return RealLiteral_N(code_range_from_ctx(ctx),
                             float(ctx.value.text))

    # Visit a parse tree produced by GeLBParser#arrayLiteralExpr.
    def visitArrayLiteralExpr(
            self,
            ctx: GeLBParser.ArrayLiteralExprContext
    ):
        if ctx.array_literal_4d():
            return self.visitArray_literal_4d(ctx.array_literal_4d())
        elif ctx.array_literal_3d():
            return self.visitArray_literal_3d(ctx.array_literal_3d())
        elif ctx.array_literal_2d():
            return self.visitArray_literal_2d(ctx.array_literal_2d())
        elif ctx.array_literal_1d():
            return self.visitArray_literal_1d(ctx.array_literal_1d())

    # Visit a parse tree produced by GeLBParser#powExpr.
    def visitPowExpr(
            self,
            ctx: GeLBParser.PowExprContext
    ):
        return Pow_N(
            code_range_from_ctx(ctx),
            self.visit(ctx.left),
            self.visit(ctx.right)
        )

    # Visit a parse tree produced by GeLBParser#boolLiteralExpr.
    def visitBoolLiteralExpr(
            self,
            ctx: GeLBParser.BoolLiteralExprContext
    ):
        return BoolLiteral_N(code_range_from_ctx(ctx), ctx.value.text)

    # Visit a parse tree produced by GeLBParser#nonNegIntLiteralExpr.
    def visitNonNegIntLiteralExpr(
            self,
            ctx: GeLBParser.NonNegIntLiteralExprContext
    ):
        return IntLiteral_N(code_range_from_ctx(ctx), int(ctx.value.text))

    # Visit a parse tree produced by GeLBParser#identifierExpr.
    def visitIdentifierExpr(
            self,
            ctx: GeLBParser.IdentifierExprContext
    ):
        return self.visitIdentifier(ctx.identifier())

    # Visit a parse tree produced by GeLBParser#comparisonExpr.
    def visitComparisonExpr(
            self,
            ctx: GeLBParser.ComparisonExprContext
    ):
        if ctx.op.text == '<':
            return Less_N(
                code_range_from_ctx(ctx),
                self.visit(ctx.left),
                self.visit(ctx.right)
            )
        elif ctx.op.text == '>':
            return Greater_N(
                code_range_from_ctx(ctx),
                self.visit(ctx.left),
                self.visit(ctx.right)
            )
        elif ctx.op.text == '<=':
            return LessEqual_N(
                code_range_from_ctx(ctx),
                self.visit(ctx.left),
                self.visit(ctx.right)
            )
        elif ctx.op.text == '>=':
            return GreaterEqual_N(
                code_range_from_ctx(ctx),
                self.visit(ctx.left),
                self.visit(ctx.right)
            )
        else:
            assert False, "Unknown comparison operator: {}".format(ctx.op.text)

    # Visit a parse tree produced by GeLBParser#equalityExpr.
    def visitEqualityExpr(
            self,
            ctx: GeLBParser.EqualityExprContext
    ):
        if ctx.op.text == '==':
            return Equal_N(
                code_range_from_ctx(ctx),
                self.visit(ctx.left),
                self.visit(ctx.right)
            )
        elif ctx.op.text == '!=':
            return NotEqual_N(
                code_range_from_ctx(ctx),
                self.visit(ctx.left),
                self.visit(ctx.right)
            )
        else:
            assert False, "Unknown equality operator: {}".format(ctx.op.text)

    # Visit a parse tree produced by GeLBParser#logicalAndExpr.
    def visitLogicalAndExpr(
            self,
            ctx: GeLBParser.LogicalAndExprContext
    ):
        return And_N(
            code_range_from_ctx(ctx),
            self.visit(ctx.left),
            self.visit(ctx.right)
        )

    # Visit a parse tree produced by GeLBParser#logicalOrExpr.
    def visitLogicalOrExpr(
            self,
            ctx: GeLBParser.LogicalOrExprContext
    ):
        return Or_N(
            code_range_from_ctx(ctx),
            self.visit(ctx.left),
            self.visit(ctx.right)
        )

    # Visit a parse tree produced by GeLBParser#intrinsicFunctionCallExpr.
    def visitIntrinsicFunctionCallExpr(
            self,
            ctx: GeLBParser.IntrinsicFunctionCallExprContext
    ):
        # Get the intrinsic function call node
        func_call_ctx = ctx.intrinsic_function_call()
        
        # Extract function name
        func_name_ctx = func_call_ctx.intrinsic_function_name()
        if func_name_ctx.SUM():
            function_name = "sum"
        elif func_name_ctx.DOT_PROD():
            function_name = "dot_prod"
        else:
            raise GeLBException(f"Unknown intrinsic function at {code_range_from_ctx(func_name_ctx)}")
        
        # Extract arguments
        arguments = List_N(code_range_from_ctx(func_call_ctx))
        if func_call_ctx.arguments:
            for arg_ctx in func_call_ctx.arguments:
                arguments.append(self.visit(arg_ctx))
        
        return IntrinsicFunctionCall_N(
            code_range_from_ctx(ctx),
            function_name,
            arguments
        )

    def get_list_of_children_sub_asts(self, ctx):
        list_of_children_sub_asts = List_N(code_range_from_ctx(ctx))
        # Strategy: visit all children nodes (based on the implementation of
        # ParseTreeVisitor.visitChildren), and append non-trivial children to
        # the list_of_children_sub_asts.
        n = ctx.getChildCount()
        
        for i in range(n):
            c = ctx.getChild(i)
            # NOTE: boring children (i.e. syntax elements which don't belong
            # inside the AST) yield child_result == None, because we DON'T
            # implement a visitor-method override for them!
            child_result = c.accept(self)
            if child_result:
                list_of_children_sub_asts.append(child_result)

        return list_of_children_sub_asts
